{
  "version": "v1",
  "hooks": [
    {
      "name": "시작",
      "trigger": "SessionStart",
      "action": {
        "type": "command",
        "command": "HX_HARNESS=kiro B_FLAG=1 bash -c 'r=\"$PWD\"; while [ \"$r\" != / ] && [ ! -f \"$r/.agents/harness-kit.json\" ] && [ ! -f \"$r/.agents/harness.json\" ]; do r=\"$(dirname \"$r\")\"; done; [ -f \"$r/scripts/hooks/dispatch.sh\" ] || exit 0; exec bash \"$r/scripts/hooks/dispatch.sh\" \"$1\" \"$2\"' _ harness-a-start scripts/hooks/a.sh",
        "timeout": 15
      }
    }
  ]
}

{
  "version": "v1",
  "hooks": [
    {
      "name": "harness-b-guard",
      "trigger": "PreToolUse",
      "description": "쓰기 · 셸 둘 다",
      "matcher": "fs_write|fs_append|str_replace|delete_file|edit_code|semantic_rename|smart_relocate|execute_bash|executeBash|shell",
      "action": {
        "type": "command",
        "command": "bash -c 'r=\"$PWD\"; while [ \"$r\" != / ] && [ ! -f \"$r/.agents/harness-kit.json\" ] && [ ! -f \"$r/.agents/harness.json\" ]; do r=\"$(dirname \"$r\")\"; done; [ -f \"$r/scripts/hooks/dispatch.sh\" ] || exit 0; exec bash \"$r/scripts/hooks/dispatch.sh\" \"$1\" \"$2\"' _ harness-b-guard scripts/hooks/b.sh",
        "timeout": 10
      }
    }
  ]
}

