        "command": "bash -c 'r=\"$PWD\"; while [ \"$r\" != / ] && [ ! -f \"$r/.agents/harness-kit.json\" ] && [ ! -f \"$r/.agents/harness.json\" ]; do r=\"$(dirname \"$r\")\"; done; [ -f \"$r/scripts/hooks/dispatch.sh\" ] || exit 0; exec bash \"$r/scripts/hooks/dispatch.sh\" \"$1\" \"$2\"' _ harness-g-stop scripts/hooks/g.sh",
        "timeout_ms": 180000
